import React from 'react';
import {
  Box,
  Typography,
  Grid,
  Card,
  CardContent,
  Chip,
  Fade,
  useTheme,
  useMediaQuery,
} from '@mui/material';
import {
  Code as CodeIcon,
  Web as WebIcon,
  Storage as StorageIcon,
  Star as StarIcon,
} from '@mui/icons-material';
import { useInView } from 'react-intersection-observer';

function Skills() {
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('sm'));

  /* ===================== SKILLS DATA ===================== */
  const skillGroups = {
    Frontend: [
      { name: 'HTML', primary: false },
      { name: 'CSS', primary: false },
      { name: 'JavaScript', primary: false },
      { name: 'React', primary: false },
      { name: 'Material UI', primary: false },
    ],
    'Database & Tools': [
      { name: 'PostgreSQL', primary: false },
      { name: 'MongoDB', primary: false },
      { name: 'Git', primary: false },
      { name: 'GitHub', primary: false },
      { name: 'Eclipse IDE', primary: false },
      { name: 'VS Code', primary: false },
    ],
    Backend: [
      { name: 'Core Java', primary: false },
      { name: 'OOPS', primary: false },
      { name: 'JDBC', primary: false },
      { name: 'Hibernate', primary: false },
      { name: 'Spring Boot', primary: false },
      { name: 'REST APIs', primary: false },
      { name: 'Microservices (Basics)', primary: false },
    ],
  };

  /* ===================== ICONS ===================== */
  const categoryIcons = {
    Frontend: <WebIcon color="primary" />,
    'Database & Tools': <StorageIcon color="primary" />,
    Backend: <CodeIcon color="primary" />,
  };

  /* ===================== ANIMATION ===================== */
  const { ref, inView } = useInView({
    triggerOnce: true,
    threshold: 0.1,
  });

  /* ===================== REUSABLE CARD ===================== */
  const renderSkillCard = (category, skills) => (
    <Card
      sx={{
        minHeight: { xs: 150, md: 160 },
        maxWidth: 400, // same width for all cards
        width: '100%',
        borderRadius: 3,
        boxShadow: 3,
        transition: 'all 0.3s ease',
        '&:hover': {
          transform: 'translateY(-8px)',
          boxShadow: 6,
        },
      }}
    >
      <CardContent sx={{ p: 3 }}>
        <Box sx={{ display: 'flex', alignItems: 'center', mb: 2 }}>
          {categoryIcons[category]}
          <Typography
            variant="h5"
            sx={{ ml: 1, fontWeight: 'bold', color: theme.palette.primary.main }}
          >
            {category}
          </Typography>
        </Box>

        <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 1 }}>
          {skills.map((skill, index) => (
            <Chip
              key={index}
              label={skill.name}
              icon={skill.primary ? <StarIcon /> : undefined}
              sx={{
                borderRadius: 2,
                fontSize: '0.9rem',
                fontWeight: skill.primary ? 'bold' : 'normal',
                backgroundColor: skill.primary
                  ? theme.palette.secondary.main
                  : theme.palette.grey[200],
                color: skill.primary
                  ? theme.palette.secondary.contrastText
                  : theme.palette.text.primary,
                transition: 'all 0.25s ease',
                '&:hover': {
                  transform: 'scale(1.05)',
                  backgroundColor: skill.primary
                    ? theme.palette.secondary.dark
                    : theme.palette.grey[300],
                },
              }}
            />
          ))}
        </Box>
      </CardContent>
    </Card>
  );

  return (
    <Box
      id="skills"
      sx={{
        py: 8,
        px: 2,
        background: 'linear-gradient(135deg, #f5f7fa 0%, #c3cfe2 100%)',
        minHeight: '100vh',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
      }}
    >
      <Box ref={ref} sx={{ maxWidth: 1200, width: '100%' }}>
        <Fade in={inView} timeout={1000}>
          <Box>
            {/* ===== TITLE ===== */}
            <Typography
              variant={isMobile ? 'h4' : 'h3'}
              align="center"
              sx={{
                fontWeight: 'bold',
                color: theme.palette.primary.main,
                mb: 3,
              }}
            >
              Skills
            </Typography>

            <Typography
              variant="body1"
              align="center"
              sx={{
                mb: 6,
                maxWidth: 850,
                mx: 'auto',
                color: theme.palette.text.secondary,
                fontSize: '1.1rem',
              }}
            >
              As a fresher Java Full Stack Developer, I focus on building strong
              backend systems using Java and Spring Boot, while continuously
              improving my frontend and database skills to create complete,
              scalable web applications.
            </Typography>

            {/* ===== GRID LAYOUT ===== */}
            <Grid container spacing={4} justifyContent="center">
              {/* Top row */}
              <Grid item xs={12} md={6} display="flex" justifyContent="center">
                {renderSkillCard('Frontend', skillGroups.Frontend)}
              </Grid>

              <Grid item xs={12} md={6} display="flex" justifyContent="center">
                {renderSkillCard('Database & Tools', skillGroups['Database & Tools'])}
              </Grid>

              {/* Backend card below, horizontally centered */}
              <Grid item xs={12} display="flex" justifyContent="center">
                {renderSkillCard('Backend', skillGroups.Backend)}
              </Grid>
            </Grid>
          </Box>
        </Fade>
      </Box>
    </Box>
  );
}

export default Skills;
